                    if (cr, cc) in visited_outer:
                        continue
                    visited_outer.add((cr, cc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and (nr, nc) not in visited_outer:
                            stack.append((nr, nc))

    # Now find inner components of 0s
    visited_inner = set()
    inner_regions = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 and (r, c) not in visited_outer and (r, c) not in visited_inner:
                region = []
                stack = [(r, c)]
                while stack:
                    cr, cc = stack.pop()
                    if (cr, cc) in visited_inner:
                        continue
                    visited_inner.add((cr, cc))
                    region.append((cr, cc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
