def find_edge_connected(grid, include_special=True):
    """Find all cells connected to any edge of the grid"""
    h, w = len(grid), len(grid[0])
    visited = set()

    # Start from edges
    edge_stack = []
    for r in range(h):
        for c in [0, w-1]:
            edge_stack.append((r, c))
    for r in [0, h-1]:
        for c in range(1, w-1):
            edge_stack.append((r, c))

    while edge_stack:
        cr, cc = edge_stack.pop()
        if (cr, cc) in visited:
            continue
        if grid[cr][cc] == 0 and not include_special:
            continue
        visited.add((cr, cc))
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = cr + dr, cc + dc
            if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in visited and grid[nr][nc] != 0:
                edge_stack.append((nr, nc))

    return visited

